// aim.cpp — controller aim assist.
//
// Projects candidate target head positions to screen space, picks the one
// closest to the crosshair inside a 240px cone, and returns a smoothed
// crosshair delta (in pixels) for the camera controller to apply.
//
// Every input comes from the game's own state: camera view-projection matrix,
// viewport size, and target positions. The engine should only call this when
// aim assist is enabled (e.g. gamepad input, single-player, or a server-
// sanctioned mode).

#include <array>
#include <cmath>
#include <cstddef>
#include <optional>
#include <vector>

namespace aim {

struct Vec2 { float x = 0, y = 0; };
struct Vec3 { float x = 0, y = 0, z = 0; };

// Column-major 4x4 (OpenGL / GLM layout): m[col * 4 + row].
struct Mat4 { std::array<float, 16> m{}; };

struct Target {
    Vec3 head;          // world-space head position
    bool alive = true;
    bool visible = true; // caller's line-of-sight result
};

struct Config {
    float coneRadiusPx = 240.0f; // max distance from crosshair, in pixels
    float smoothing    = 8.0f;   // higher = snappier (1/s, exponential approach)
    float strength     = 1.0f;   // 0..1 overall scale on the correction
    float maxStepPx    = 40.0f;  // per-frame clamp on the correction
};

struct State {
    Vec2 smoothed{};                  // last smoothed delta
    std::optional<std::size_t> lock;  // index of the current target, if any
};

// World -> screen. Returns nullopt if the point is behind the camera or
// outside the clip volume. Screen origin is top-left, y down.
std::optional<Vec2> worldToScreen(const Vec3& p, const Mat4& viewProj,
                                  float viewportW, float viewportH) {
    const auto& m = viewProj.m;
    float cx = m[0] * p.x + m[4] * p.y + m[8]  * p.z + m[12];
    float cy = m[1] * p.x + m[5] * p.y + m[9]  * p.z + m[13];
    float cz = m[2] * p.x + m[6] * p.y + m[10] * p.z + m[14];
    float cw = m[3] * p.x + m[7] * p.y + m[11] * p.z + m[15];

    if (cw <= 1e-5f) return std::nullopt; // behind camera

    float nx = cx / cw, ny = cy / cw, nz = cz / cw;
    if (nx < -1 || nx > 1 || ny < -1 || ny > 1 || nz < -1 || nz > 1)
        return std::nullopt;

    return Vec2{ (nx * 0.5f + 0.5f) * viewportW,
                 (1.0f - (ny * 0.5f + 0.5f)) * viewportH };
}

// Returns the crosshair delta (pixels) to apply this frame. Zero if no target
// is inside the cone. `dt` is the frame time in seconds.
Vec2 computeDelta(const std::vector<Target>& targets, const Mat4& viewProj,
                  float viewportW, float viewportH, float dt,
                  const Config& cfg, State& state) {
    const Vec2 center{ viewportW * 0.5f, viewportH * 0.5f };
    const float r2 = cfg.coneRadiusPx * cfg.coneRadiusPx;

    std::optional<std::size_t> best;
    Vec2 bestOffset{};
    float bestD2 = r2;

    for (std::size_t i = 0; i < targets.size(); ++i) {
        const Target& t = targets[i];
        if (!t.alive || !t.visible) continue;

        auto s = worldToScreen(t.head, viewProj, viewportW, viewportH);
        if (!s) continue;

        Vec2 off{ s->x - center.x, s->y - center.y };
        float d2 = off.x * off.x + off.y * off.y;

        // Slight preference for the current target to avoid flicking
        // between two targets at similar distances.
        if (state.lock && *state.lock == i) d2 *= 0.8f;

        if (d2 < bestD2) {
            bestD2 = d2;
            best = i;
            bestOffset = off;
        }
    }

    state.lock = best;

    Vec2 desired{};
    if (best) {
        // Fade the pull out toward the cone edge so it doesn't snap on entry.
        float dist = std::sqrt(bestOffset.x * bestOffset.x + bestOffset.y * bestOffset.y);
        float falloff = 1.0f - std::fmin(dist / cfg.coneRadiusPx, 1.0f);
        float k = cfg.strength * falloff;
        desired = { bestOffset.x * k, bestOffset.y * k };
    }

    // Frame-rate-independent exponential smoothing.
    float a = 1.0f - std::exp(-cfg.smoothing * dt);
    state.smoothed.x += (desired.x - state.smoothed.x) * a;
    state.smoothed.y += (desired.y - state.smoothed.y) * a;

    Vec2 out = state.smoothed;
    float len = std::sqrt(out.x * out.x + out.y * out.y);
    if (len > cfg.maxStepPx && len > 0) {
        float s = cfg.maxStepPx / len;
        out.x *= s;
        out.y *= s;
    }
    return out;
}

} // namespace aim
